  'dc6aed59f8e': DhikrEnglish(
    subtitle: 'What is said between the adhan and the iqama',
    text:
        'Between the adhan and the iqama, making dua is encouraged and recommended. The Messenger of Allah (peace and blessings be upon him) said: "Dua is not rejected between the adhan and the iqama." He (peace and blessings be upon him) also said: "Dua is not rejected between the adhan and the iqama, so make dua."',
